import{_ as a,a0 as r,w as l,s as d,I as p,x as t,a1 as n,A as o,ao as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"試試Linux下的ip命令，ifconfig已經過時了 | LCTT x X-CMD","titleTemplate":false,"description":"試試Linux下的ip命令，ifconfig已經過時了 | LCTT (201406) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"試試Linux下的ip命令，ifconfig已經過時了 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"試試Linux下的ip命令，ifconfig已經過時了 | LCTT (201406) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201406/Start Practising Linux ip command and Avoid the Habit of Using ifconfig","title":"試試Linux下的ip命令，ifconfig已經過時了","tag":"201406","desc":""},"relativePath":"201406/Start Practising Linux ip command and Avoid the Habit of Using ifconfig.md","filePath":"[post].md"}'),u={name:"201406/Start Practising Linux ip command and Avoid the Habit of Using ifconfig.md"};function m(g,i,c,f,h,x){const e=r("Link");return l(),d("div",null,[i[16]||(i[16]=p("h1",{id:"試試linux下的ip命令-ifconfig已經過時了",tabindex:"-1"},[t("試試Linux下的ip命令，ifconfig已經過時了 "),p("a",{class:"header-anchor",href:"#試試linux下的ip命令-ifconfig已經過時了","aria-label":"Permalink to “試試Linux下的ip命令，ifconfig已經過時了”"},"​")],-1)),i[17]||(i[17]=p("p",null,[t("linux的"),p("strong",null,"ip"),t("命令和"),p("strong",null,"ifconfig"),t("類似，但前者功能更強大，並旨在取代後者。使用ip命令，只需一個命令，你就能很輕鬆地執行一些網絡管理任務。ifconfig是net-tools中已被廢棄使用的一個命令，許多年前就已經沒有維護了。iproute2套件裏提供了許多增強功能的命令，ip命令即是其中之一。")],-1)),i[18]||(i[18]=p("p",null,[p("img",{src:"http://linoxide.com/wp-content/uploads/2014/05/Linux-Nettools-vs-Iproute2.png",alt:"Net tools vs Iproute2"})],-1)),p("p",null,[i[1]||(i[1]=t("要安裝ip，請",-1)),n(e,{href:"http://www.linuxgrill.com/anonymous/iproute2/NEW-OSDL/"},{default:o(()=>[...i[0]||(i[0]=[t("點擊這裏",-1)])]),_:1}),i[2]||(i[2]=t("下載",-1)),i[3]||(i[3]=p("strong",null,"iproute2套裝工具",-1)),i[4]||(i[4]=t(" 。不過，大多數Linux發行版已經預裝了iproute2工具。",-1))]),i[19]||(i[19]=s(`<p>你也可以使用git命令來下載最新源代碼來編譯：</p><pre><code>$ git clone https://kernel.googlesource.com/pub/scm/linux/kernel/git/shemminger/iproute2.git
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/04/iproute2-git-clone.png" alt="iproute2 git clone"></p><h3 id="設置和刪除ip地址" tabindex="-1">設置和刪除Ip地址 <a class="header-anchor" href="#設置和刪除ip地址" aria-label="Permalink to “設置和刪除Ip地址”">​</a></h3><p>要給你的機器設置一個IP地址，可以使用下列ip命令：</p><pre><code>$ sudo ip addr add 192.168.0.193/24 dev wlan0
</code></pre><p>請注意IP地址要有一個後綴，比如/24。這種用法用於在無類域內路由選擇（CIDR）中來顯示所用的子網掩碼。在這個例子中，子網掩碼是255.255.255.0。</p><p>在你按照上述方式設置好IP地址後，需要查看是否已經生效。</p><pre><code>$ ip addr show wlan0
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/04/set-ip-address.png" alt="set ip address"></p><p>你也可以使用相同的方式來刪除IP地址，只需用del代替add。</p><pre><code>$ sudo ip addr del 192.168.0.193/24 dev wlan0
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/04/delete-ip-address.png" alt="delete ip address"></p><h3 id="列出路由表條目" tabindex="-1">列出路由表條目 <a class="header-anchor" href="#列出路由表條目" aria-label="Permalink to “列出路由表條目”">​</a></h3><p>ip命令的路由對象的參數還可以幫助你查看網絡中的路由數據，並設置你的路由表。第一個條目是默認的路由條目，你可以隨意改動它。</p><p>在這個例子中，有幾個路由條目。這個結果顯示有幾個設備通過不同的網絡接口連接起來。它們包括WIFI、以太網和一個點對點連接。</p><pre><code>$ ip route show
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/04/ip-route-show.png" alt="ip route show"></p><p>假設現在你有一個IP地址，你需要知道路由包從哪裏來。可以使用下面的路由選項（譯註：列出了路由所使用的接口等）：</p><pre><code>$ ip route get 10.42.0.47
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/04/ip-route-get.png" alt="ip route get"></p><h3 id="更改默認路由" tabindex="-1">更改默認路由 <a class="header-anchor" href="#更改默認路由" aria-label="Permalink to “更改默認路由”">​</a></h3><p>要更改默認路由，使用下面ip命令：</p><pre><code>$ sudo ip route add default via 192.168.0.196
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/04/default-route.png" alt="default route"></p><h3 id="顯示網絡統計數據" tabindex="-1">顯示網絡統計數據 <a class="header-anchor" href="#顯示網絡統計數據" aria-label="Permalink to “顯示網絡統計數據”">​</a></h3><p>使用ip命令還可以顯示不同網絡接口的統計數據。</p><p><img src="http://linoxide.com/wp-content/uploads/2014/04/ip-statistics-all-interfaces.png" alt="ip statistics all interfaces"></p><p>當你需要獲取一個特定網絡接口的信息時，在網絡接口名字後面添加選項<strong>ls</strong>即可。使用多個選項<strong>-s</strong>會給你這個特定接口更詳細的信息。特別是在排除網絡連接故障時，這會非常有用。</p><pre><code>$ ip -s -s link ls p2p1
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/04/ip-link-statistics-.png" alt="ip link statistics"></p><h3 id="arp條目" tabindex="-1">ARP條目 <a class="header-anchor" href="#arp條目" aria-label="Permalink to “ARP條目”">​</a></h3><p>地址解析協議（ARP）用於將一個IP地址轉換成它對應的物理地址，也就是通常所説的MAC地址。使用ip命令的neigh或者neighbour選項，你可以查看接入你所在的局域網的設備的MAC地址。</p><pre><code>$ ip neighbour
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/04/ip-neighbour.png" alt="ip neighbour"></p><h3 id="監控netlink消息" tabindex="-1">監控netlink消息 <a class="header-anchor" href="#監控netlink消息" aria-label="Permalink to “監控netlink消息”">​</a></h3><p>也可以使用ip命令查看netlink消息。monitor選項允許你查看網絡設備的狀態。比如，所在局域網的一台電腦根據它的狀態可以被分類成REACHABLE或者STALE。使用下面的命令：</p><pre><code>$ ip monitor all
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/04/ip-monitor-all.png" alt="ip monitor all"></p><h3 id="激活和停止網絡接口" tabindex="-1">激活和停止網絡接口 <a class="header-anchor" href="#激活和停止網絡接口" aria-label="Permalink to “激活和停止網絡接口”">​</a></h3><p>你可以使用ip命令的up和down選項來激某個特定的接口，就像ifconfig的用法一樣。</p><p>在這個例子中，當ppp0接口被激活和在它被停止和再次激活之後，你可以看到相應的路由表條目。這個接口可能是wlan0或者eth0。將ppp0更改為你可用的任意接口即可。</p><pre><code>$ sudo ip link set ppp0 down

$ sudo ip link set ppp0 up
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/04/ip-link-set-up-and-down.png" alt="ip link set up and down"></p><h3 id="獲取幫助" tabindex="-1">獲取幫助 <a class="header-anchor" href="#獲取幫助" aria-label="Permalink to “獲取幫助”">​</a></h3><p>當你陷入困境，不知道某一個特定的選項怎麼用的時候，你可以使用help選項。man頁面並不會提供許多關於如何使用ip選項的信息，因此這裏就是獲取幫助的地方。</p><p>比如，想知道關於route選項更多的信息：</p><pre><code>$ ip route help
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/04/ip-route-help.png" alt="ip route help"></p><h3 id="小結" tabindex="-1">小結 <a class="header-anchor" href="#小結" aria-label="Permalink to “小結”">​</a></h3><p>對於網絡管理員們和所有的Linux使用者們，ip命令是必備工具。是時候拋棄ifconfig命令了，特別是當你寫腳本時。</p><hr>`,52)),p("p",null,[i[6]||(i[6]=t("via: ",-1)),n(e,{href:"http://linoxide.com/linux-command/use-ip-command-linux/"},{default:o(()=>[...i[5]||(i[5]=[t("http://linoxide.com/linux-command/use-ip-command-linux/",-1)])]),_:1})]),p("p",null,[i[9]||(i[9]=t("譯者：",-1)),n(e,{href:"https://github.com/KayGuoWhu"},{default:o(()=>[...i[7]||(i[7]=[t("KayGuoWhu",-1)])]),_:1}),i[10]||(i[10]=t(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:o(()=>[...i[8]||(i[8]=[t("wxy",-1)])]),_:1})]),p("p",null,[i[13]||(i[13]=t("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...i[11]||(i[11]=[t("LCTT",-1)])]),_:1}),i[14]||(i[14]=t(" 原創翻譯，",-1)),n(e,{href:"http://linux.cn/"},{default:o(()=>[...i[12]||(i[12]=[t("Linux中國",-1)])]),_:1}),i[15]||(i[15]=t(" 榮譽推出",-1))])])}const P=a(u,[["render",m]]);export{k as __pageData,P as default};
